// Owner: B (Frontend)
// Purpose: API calls for samples
//
// CONTRACT 10, Samples (backend T21). The sample code is generated by the database
// (register_sample()); a status change must follow CONTRACT section 3 (409 invalid_transition
// otherwise) and is recorded in the sample's status history.

import type { CreateSampleRequest, Sample, SampleStatus } from '../types';
import { api } from './apiClient';

export async function createSample(body: CreateSampleRequest): Promise<Sample> {
  return (await api.post<Sample>('/samples', body)).data;
}

export async function changeSampleStatus(
  sampleId: number,
  newStatus: SampleStatus,
): Promise<Sample> {
  return (await api.patch<Sample>(`/samples/${sampleId}/status`, { new_status: newStatus })).data;
}
